// WorkerPTOPolicyAssignmentsSchema returns the schema of worker_pto_policy_assignments.
func WorkerPTOPolicyAssignmentsSchema() *schema.Table { return &workerPTOPolicyAssignmentsTable }

// As returns a handle that references worker_pto_policy_assignments under its own alias.
func (t *WorkerPTOPolicyAssignmentsTable) As(alias string) *WorkerPTOPolicyAssignmentsTable {
	return keel.Alias(t.Ref, alias, BuildWorkerPTOPolicyAssignments)
}

// Policy is the belongs relation.
func (t *WorkerPTOPolicyAssignmentsTable) Policy() *PTOPoliciesTable {
	return keel.Path(t.Ref, 0, BuildPTOPolicies)
}

// Worker is the belongs relation.
func (t *WorkerPTOPolicyAssignmentsTable) Worker() *workerdb.WorkersTable {
	return keel.Path(t.Ref, 1, workerdb.BuildWorkers)
}

// Get returns the worker_pto_policy_assignments row with the given key, or keel.ErrNotFound.
func (t *WorkerPTOPolicyAssignmentsTable) Get(ctx context.Context, db *keel.DB, key pulid.ID) (*pto.WorkerPTOPolicyAssignment, error) {
	return t.Where(t.ID.Eq(key)).One(ctx, db)
}

func newWorkerPTOPolicyAssignment() unsafe.Pointer {
	return unsafe.Pointer(new(pto.WorkerPTOPolicyAssignment))
}

func newNWorkerPTOPolicyAssignment(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]pto.WorkerPTOPolicyAssignment, n)))
}

func ptrWorkerPTOPolicyAssignment(p unsafe.Pointer, c int32) any {
	r := (*pto.WorkerPTOPolicyAssignment)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return (*string)(unsafe.Pointer(&r.WorkerID))
	case 4:
		return (*string)(unsafe.Pointer(&r.PTOPolicyID))
	case 5:
		return &r.EffectiveFrom
	case 6:
		return &r.EffectiveTo
	case 7:
		return (*string)(unsafe.Pointer(&r.AssignedByID))
	case 8:
		return &r.Note
	case 9:
		return &r.Version
	case 10:
		return &r.CreatedAt
	case 11:
		return &r.UpdatedAt
	}
	return nil
}

func valueWorkerPTOPolicyAssignment(p unsafe.Pointer, c int32) any {
	r := (*pto.WorkerPTOPolicyAssignment)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return string(r.WorkerID)
	case 4:
		return string(r.PTOPolicyID)
	case 5:
		return r.EffectiveFrom
	case 6:
		if r.EffectiveTo == nil {
			return nil
		}
		return *r.EffectiveTo
	case 7:
		if r.AssignedByID == "" {
			return nil
		}
		return string(r.AssignedByID)
	case 8:
		if r.Note == "" {
			return nil
		}
		return r.Note
	case 9:
		return r.Version
	case 10:
		return r.CreatedAt
	case 11:
		return r.UpdatedAt
	}
	return nil
}

func attachWorkerPTOPolicyAssignment(p unsafe.Pointer, rel int32, child unsafe.Pointer) {
	r := (*pto.WorkerPTOPolicyAssignment)(p)
	switch rel {
	case 0:
		r.Policy = (*pto.PTOPolicy)(child)
	case 1:
		r.Worker = (*worker.Worker)(child)
	}
}

func init() {
	pTOPoliciesTable.Relations[0].Target = PTOPolicyRulesSchema()
	workerPTOBalancesTable.Relations[0].Target = workerdb.WorkersSchema()
	workerPTOLedgerEntriesTable.Relations[0].Target = workerdb.WorkersSchema()
	workerPTOLedgerEntriesTable.Relations[1].Target = workerdb.WorkerPTOsSchema()
	workerPTOPolicyAssignmentsTable.Relations[0].Target = PTOPoliciesSchema()
	workerPTOPolicyAssignmentsTable.Relations[1].Target = workerdb.WorkersSchema()
}

